  for (var i = 0; i < lines.length && i < 4; i++) { ptext(lines[i], x, yy, 12, '#1a1a1a'); yy += 17; }
}

/* ── legend ───────────────────────────────────────────────────────────── */
function drawLegend() {
  legL.clear();
  var items = (state.scheme === 'type')
    ? [['#e7ddf3', 'Alkali metal  (1+)'], ['#e2f0d9', 'Alkaline earth  (2+)'], ['#f7f0d9', 'Transition metal  (variable)'],
       ['#e8c5c0', 'Nonmetal  (3−, 2−)'], ['#e0e0f7', 'Halogen  (1−)'], ['#bff5f5', 'Noble gas  (no ion)'],
       ['#ddf0e0', 'Lanthanide'], ['#f6dcf0', 'Actinide'], ['#ffffff', 'No simple ion shown']]
    : [['#b2182b', '6+'], ['#d6604d', '3+'], ['#f4a582', '2+'], ['#fddbc7', '1+'], ['#cfcfcf', 'variable (d-block)'],
       ['#d1e5f0', '1−'], ['#92c5de', '2−'], ['#4393c3', '3−'], ['#2166ac', '4−'], ['#ffffff', 'neutral (noble gas)']];
  legL.text(state.scheme === 'type' ? 'Color: element type' : 'Color: ionic charge')
    .font({ family: FONT, size: 10.5, weight: 'bold' }).fill('#333').move(20, 630);
  for (var i = 0; i < items.length; i++) {
    var yy = 648 + i * 14;
    legL.rect(10, 10).move(20, yy).fill(items[i][0]).stroke({ color: '#8a8a8a', width: 0.9 });
    legL.text(items[i][1]).font({ family: FONT, size: 9.5 }).fill('#333').move(35, yy - 2);
  }
}

/* ── scheme + highlight ───────────────────────────────────────────────── */
function applyScheme() {
  cells.forEach(function (c) { c.rect.fill(fillFor(c)); drawLabels(c); });
  drawLegend();
  updatePanel();
}

function update_groupSweep(v) {
  state.hg = v;
  state.selected = null;
  cells.forEach(function (c) { c.node.opacity(v === 0 || c.g === v ? 1 : 0.2); });
  var fOn = (v === 0 || v === 3) ? 1 : 0.2;
  fL.opacity(fOn); markL.opacity(fOn);
  for (var g in headers) headers[g].opacity(v === 0 || +g === v ? 1 : 0.25);
  if (v === 0) { hiRect.opacity(0); }
  else {
    var t = colTop(v);
    hiRect.size(CW + 10, gy(7) + CH + 5 - (gy(t) - 5)).move(gx(v) - 5, gy(t) - 5).opacity(1);
  }
  updatePanel();
}

function toggle_colorScheme(on) {
  state.scheme = on ? 'charge' : 'type';
  applyScheme();
}

function showInsight() {
  showPopup('Key insight',
    'Ionic charge is not memorized element by element — it is read off the column. Main-group elements gain or lose however many electrons it takes to reach the nearest noble gas, so group 1 gives 1+, group 2 gives 2+, group 16 gives 2− and group 17 gives 1−. The d-block is the region where that shortcut stops working, because s and d electrons are close enough in energy that several charges are possible.');
}

